insert into public.book_quiz (book_key, book_title, tier, question, options, answer, explanation) values
('la ferme des animaux', 'La Ferme des animaux', 50, 'Comment Napoléon se débarrasse-t-il de son rival Boule de Neige ?', '["Il l''envoie vendre du blé chez Pilkington","Il le fait chasser par ses chiens dressés","Il le bat lors d''un vote et l''exile","Il le dénonce à Jones pour qu''il le capture"]'::jsonb, 1, 'Napoléon a pris les chiots à leur naissance pour les éduquer lui-même. Devenus des molosses, ils chassent Boule de Neige : c''est le début de la dictature des cochons.'),
('la ferme des animaux', 'La Ferme des animaux', 100, 'Que voient les animaux par la fenêtre à la toute dernière scène ?', '["Jones revenir avec ses hommes reprendre la ferme","Des hommes armés encercler la ferme de nuit","Cochons et fermiers jouer aux cartes ensemble","Les cochons se battre entre eux autour de la table"]'::jsonb, 2, 'Les cochons trinquent avec les fermiers voisins : ils sont devenus semblables aux hommes qu''ils avaient chassés. C''est la chute du livre : le pouvoir a corrompu la révolution.'),
('animal farm', 'Animal Farm', 50, 'Comment Napoléon se débarrasse-t-il de son rival Boule de Neige ?', '["Il l''envoie vendre du blé chez Pilkington","Il le fait chasser par ses chiens dressés","Il le bat lors d''un vote et l''exile","Il le dénonce à Jones pour qu''il le capture"]'::jsonb, 1, 'Napoléon a pris les chiots à leur naissance pour les éduquer lui-même. Devenus des molosses, ils chassent Boule de Neige : c''est le début de la dictature des cochons.'),
('animal farm', 'Animal Farm', 100, 'Que voient les animaux par la fenêtre à la toute dernière scène ?', '["Jones revenir avec ses hommes reprendre la ferme","Des hommes armés encercler la ferme de nuit","Cochons et fermiers jouer aux cartes ensemble","Les cochons se battre entre eux autour de la table"]'::jsonb, 2, 'Les cochons trinquent avec les fermiers voisins : ils sont devenus semblables aux hommes qu''ils avaient chassés. C''est la chute du livre : le pouvoir a corrompu la révolution.'),
('the little prince', 'The Little Prince', 50, 'Pourquoi le buveur, sur sa planète, continue-t-il de boire ?', '["Pour oublier qu''il a honte de boire","Parce que le roi le lui a ordonné","Parce qu''il s''ennuie sur sa planète déserte","Pour fêter une victoire qu''il a remportée"]'::jsonb, 0, 'Le buveur est enfermé dans un cercle absurde : il boit pour oublier la honte… de boire. Le petit prince repart perplexe, comme à chaque rencontre d''adulte.'),
('the little prince', 'The Little Prince', 100, 'Comment le petit prince retourne-t-il sur sa planète ?', '["En traversant le désert jusqu''à la mer","En suivant une migration d''oiseaux sauvages","Avec l''avion réparé par le narrateur","En se laissant mordre par le serpent jaune"]'::jsonb, 3, 'Le serpent promet de le renvoyer d''où il vient : son corps reste, mais il retrouve sa planète et sa rose. Le narrateur, lui, répare son moteur et garde les étoiles qui rient.'),
('le petit prince', 'Le Petit Prince', 50, 'Pourquoi le buveur, sur sa planète, continue-t-il de boire ?', '["Pour oublier qu''il a honte de boire","Parce que le roi le lui a ordonné","Parce qu''il s''ennuie sur sa planète déserte","Pour fêter une victoire qu''il a remportée"]'::jsonb, 0, 'Le buveur est enfermé dans un cercle absurde : il boit pour oublier la honte… de boire. Le petit prince repart perplexe, comme à chaque rencontre d''adulte.'),
('le petit prince', 'Le Petit Prince', 100, 'Comment le petit prince retourne-t-il sur sa planète ?', '["En traversant le désert jusqu''à la mer","En suivant une migration d''oiseaux sauvages","Avec l''avion réparé par le narrateur","En se laissant mordre par le serpent jaune"]'::jsonb, 3, 'Le serpent promet de le renvoyer d''où il vient : son corps reste, mais il retrouve sa planète et sa rose. Le narrateur, lui, répare son moteur et garde les étoiles qui rient.'),
('l etranger', 'L''étranger', 50, 'Quelle raison Meursault donne-t-il pour avoir tiré sur l''Arabe ?', '["Un ordre de Raymond","Il a eu peur d''un complot","Une vengeance personnelle","À cause du soleil"]'::jsonb, 3, 'Aveuglé par la lumière et la chaleur sur la plage, il tire. Le « c''était à cause du soleil » est l''une des répliques les plus célèbres du roman.'),
('l etranger', 'L''étranger', 100, 'Que souhaite Meursault à la dernière phrase, avant son exécution ?', '["Que beaucoup de spectateurs viennent le huer","Que le président lui accorde sa grâce","Revoir Marie une toute dernière fois","Fumer une dernière cigarette en paix"]'::jsonb, 0, 'Réconcilié avec sa condition après sa colère contre l''aumônier, il souhaite être haï pour se sentir moins seul. Il accepte ainsi l''indifférence « tendre » du monde.'),
('fahrenheit 451', 'Fahrenheit 451', 50, 'Selon le capitaine Beatty, pourquoi a-t-on fini par brûler les livres ?', '["Pour ne vexer aucune minorité ni aucun groupe","Pour faire oublier les horreurs de la guerre","À cause d''une loi votée après la guerre","Parce que les gens ne savaient plus lire"]'::jsonb, 0, 'Beatty raconte que les minorités et les groupes se sentaient visés ; on a peu à peu tout aplani, jusqu''à rendre les livres inutiles. Les citoyens ont, selon lui, choisi eux-mêmes le divertissement facile.'),
('fahrenheit 451', 'Fahrenheit 451', 100, 'Comment les exilés que Montag rencontre à la fin conservent-ils les livres ?', '["En les cachant dans des grottes","En les apprenant par cœur","En les enterrant","En les imprimant en secret"]'::jsonb, 1, 'Chacun mémorise un livre : ce sont des « hommes-livres ». Ils sauront reconstruire la culture après la guerre qui détruit la ville.'),
('harry potter and the sorcerer s stone harry potter 1', 'Harry Potter and the Sorcerer''s Stone (Harry Potter, #1)', 50, 'Qui Harry et Ron sauvent-ils du troll, à Halloween ?', '["Ginny","Dean","Hermione","Neville"]'::jsonb, 2, 'Hermione se cache pleurant dans les toilettes quand le troll arrive. Cette aventure commune scelle l''amitié du trio.'),
('harry potter and the sorcerer s stone harry potter 1', 'Harry Potter and the Sorcerer''s Stone (Harry Potter, #1)', 100, 'Qui voulait voler la pierre philosophale, et à qui obéissait-il ?', '["Quirrell, avec Voldemort sur la nuque","Rogue, fidèle serviteur de Dumbledore","Hagrid, pour récupérer son dragon","Malefoy, sur ordre de son père"]'::jsonb, 0, 'Le timide professeur Quirrell est possédé par Voldemort : son visage apparaît à l''arrière de sa tête. Rogue, soupçonné, protégeait en fait Harry.'),
('harry potter and the philosopher s stone', 'Harry Potter and the Philosopher''s Stone', 50, 'Qui Harry et Ron sauvent-ils du troll, à Halloween ?', '["Ginny","Dean","Hermione","Neville"]'::jsonb, 2, 'Hermione se cache pleurant dans les toilettes quand le troll arrive. Cette aventure commune scelle l''amitié du trio.'),
